-- W07_PAYMENT_SOURCE_SHA256=a272fe9716afda888b9a543911356da729f7079080ddc75a72a96418daefb9f8
-- ORDER_PERSISTENCE_CONTRACT_SHA256=29354855a73dac7c08c4a221410df799b2c4d97df38bdb383a32735d8052790a
-- PAYMENT_PERSISTENCE_CONTRACT_SHA256=55b84cbf321eb9a69db0553249eb16462567028266860dec1abbeb2e27149254
