-- PAYMENT_STATE_MACHINE_SHA256=88a0faf7cc7146962cdd87c0bb835ecfb9ebe68160e87e28f6f042e3561ae957
-- D1_04_OWNER_LEDGER_CONTRACT_SHA256=cb867e81ea395b0a652173b672ed40a3217ba42f875bf5a1302d484f574f7da5

CREATE TABLE orders (
  order_id TEXT PRIMARY KEY NOT NULL CHECK (char_length(order_id) BETWEEN 1 AND 255),
  customer_id TEXT NOT NULL CHECK (char_length(customer_id) BETWEEN 1 AND 256),
  status TEXT NOT NULL CHECK (status IN ('CREATED','PENDING_PAYMENT','CONFIRMED','PROCESSING','COMPLETED','CANCELLED','FAILED')),
  version BIGINT NOT NULL DEFAULT 1 CHECK (version >= 1),
  currency TEXT NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  subtotal_minor BIGINT NOT NULL CHECK (subtotal_minor BETWEEN 0 AND 9007199254740991),
  discount_minor BIGINT NOT NULL CHECK (discount_minor BETWEEN 0 AND subtotal_minor),
  tax_minor BIGINT NOT NULL CHECK (tax_minor BETWEEN 0 AND 9007199254740991),
  total_minor BIGINT NOT NULL CHECK (
    total_minor BETWEEN 0 AND 9007199254740991
    AND total_minor = subtotal_minor - discount_minor + tax_minor
  ),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL CHECK (updated_at >= created_at),
  confirmed_at TIMESTAMPTZ,
  cancelled_at TIMESTAMPTZ,
  failure_code TEXT CHECK (failure_code IS NULL OR char_length(failure_code) BETWEEN 1 AND 128)
);

CREATE INDEX ix_orders_customer_created_order ON orders(customer_id, created_at, order_id);
CREATE INDEX ix_orders_status_created_order ON orders(status, created_at, order_id);

CREATE TABLE order_lines (
  order_line_id TEXT PRIMARY KEY NOT NULL CHECK (char_length(order_line_id) BETWEEN 1 AND 255),
  order_id TEXT NOT NULL CHECK (char_length(order_id) BETWEEN 1 AND 255),
  item_type TEXT NOT NULL CHECK (item_type IN ('CONTENT','MEMBERSHIP_PLAN','DIGITAL_GOOD','BUNDLE')),
  item_ref TEXT NOT NULL CHECK (char_length(item_ref) BETWEEN 1 AND 255),
  item_version TEXT NOT NULL CHECK (char_length(item_version) BETWEEN 1 AND 255),
  quantity BIGINT NOT NULL CHECK (quantity BETWEEN 1 AND 10000),
  unit_amount_minor BIGINT NOT NULL CHECK (
    unit_amount_minor BETWEEN 0 AND 9007199254740991
    AND unit_amount_minor::numeric * quantity::numeric <= 9007199254740991
  ),
  line_subtotal_minor BIGINT NOT NULL CHECK (
    line_subtotal_minor BETWEEN 0 AND 9007199254740991
    AND line_subtotal_minor::numeric = unit_amount_minor::numeric * quantity::numeric
  ),
  line_discount_minor BIGINT NOT NULL CHECK (line_discount_minor BETWEEN 0 AND line_subtotal_minor),
  line_tax_minor BIGINT NOT NULL CHECK (line_tax_minor BETWEEN 0 AND 9007199254740991),
  line_total_minor BIGINT NOT NULL CHECK (
    line_total_minor BETWEEN 0 AND 9007199254740991
    AND line_total_minor = line_subtotal_minor - line_discount_minor + line_tax_minor
  ),
  item_snapshot_json TEXT NOT NULL CHECK (
    octet_length(item_snapshot_json) BETWEEN 2 AND 65536
    AND jsonb_typeof(item_snapshot_json::jsonb) = 'object'
  ),
  created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX ix_order_lines_order_id ON order_lines(order_id);
CREATE INDEX ix_order_lines_item_ref_version ON order_lines(item_ref, item_version);

CREATE TABLE order_create_idempotency (
  id TEXT PRIMARY KEY NOT NULL CHECK (char_length(id) BETWEEN 1 AND 255),
  customer_id TEXT NOT NULL CHECK (char_length(customer_id) BETWEEN 1 AND 256),
  operation_key TEXT NOT NULL CHECK (operation_key = 'POST /v1/commerce/orders'),
  idempotency_key TEXT NOT NULL CHECK (char_length(idempotency_key) BETWEEN 1 AND 256),
  request_hash TEXT NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  state TEXT NOT NULL CHECK (state IN ('IN_PROGRESS','COMPLETED','FAILED')),
  response_status INTEGER CHECK (response_status IS NULL OR response_status BETWEEN 100 AND 599),
  response_json TEXT CHECK (
    response_json IS NULL
    OR (octet_length(response_json) <= 65536 AND response_json::jsonb IS NOT NULL)
  ),
  created_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL CHECK (expires_at > created_at),
  UNIQUE (customer_id, operation_key, idempotency_key),
  CHECK (
    (state = 'IN_PROGRESS' AND response_status IS NULL AND response_json IS NULL)
    OR (state = 'COMPLETED' AND response_status IS NOT NULL AND response_status BETWEEN 100 AND 599 AND response_json IS NOT NULL)
    OR (state = 'FAILED' AND (
      (response_status IS NULL AND response_json IS NULL)
      OR (response_status IS NOT NULL AND response_status BETWEEN 400 AND 599 AND response_json IS NOT NULL)
    ))
  )
);
CREATE INDEX ix_order_create_idempotency_customer_created ON order_create_idempotency(customer_id, created_at);
CREATE INDEX ix_order_create_idempotency_expiration ON order_create_idempotency(expires_at);

CREATE TABLE payments (
  payment_id TEXT PRIMARY KEY NOT NULL
    CHECK (char_length(payment_id) = 30 AND payment_id ~ '^pay_[A-Za-z0-9]{26}$'),
  order_id TEXT NOT NULL CHECK (char_length(order_id) BETWEEN 1 AND 255),
  customer_id TEXT NOT NULL CHECK (char_length(customer_id) BETWEEN 1 AND 256),
  provider TEXT NOT NULL CHECK (provider = 'hyperswitch'),
  merchant_id TEXT NOT NULL CHECK (char_length(merchant_id) BETWEEN 1 AND 256),
  amount_minor BIGINT NOT NULL CHECK (amount_minor BETWEEN 1 AND 9007199254740991),
  currency TEXT NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  status TEXT NOT NULL CHECK (status IN (
    'INITIATING','requires_payment_method','requires_confirmation','requires_customer_action',
    'requires_merchant_action','requires_capture','processing','succeeded','failed','cancelled',
    'cancelled_post_capture','partially_captured','partially_captured_and_capturable','expired'
  )),
  version BIGINT NOT NULL DEFAULT 1 CHECK (version >= 1),
  idempotency_key TEXT NOT NULL CHECK (char_length(idempotency_key) BETWEEN 1 AND 128),
  request_hash TEXT NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  provider_updated_at TIMESTAMPTZ,
  failure_code TEXT CHECK (failure_code IS NULL OR char_length(failure_code) BETWEEN 1 AND 128),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL CHECK (updated_at >= created_at),
  UNIQUE (customer_id, idempotency_key)
);
CREATE INDEX ix_payments_customer_created_payment ON payments(customer_id, created_at, payment_id);
CREATE INDEX ix_payments_order_created_payment ON payments(order_id, created_at, payment_id);
CREATE INDEX ix_payments_status_updated_payment ON payments(status, updated_at, payment_id);
CREATE UNIQUE INDEX ux_payments_single_live_or_successful_per_order
  ON payments(order_id)
  WHERE status NOT IN ('failed','cancelled','cancelled_post_capture','expired');

CREATE TABLE payment_provider_events (
  event_row_id TEXT PRIMARY KEY NOT NULL CHECK (char_length(event_row_id) BETWEEN 1 AND 255),
  provider TEXT NOT NULL CHECK (provider = 'hyperswitch'),
  merchant_id TEXT NOT NULL CHECK (char_length(merchant_id) BETWEEN 1 AND 256),
  event_id TEXT NOT NULL CHECK (char_length(event_id) BETWEEN 1 AND 255),
  event_type TEXT NOT NULL CHECK (char_length(event_type) BETWEEN 1 AND 96),
  payment_id TEXT CHECK (payment_id IS NULL OR char_length(payment_id) BETWEEN 1 AND 255),
  payload_sha256 TEXT NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
  state TEXT NOT NULL DEFAULT 'RECEIVED' CHECK (state IN ('RECEIVED','APPLIED','RECONCILIATION_REQUIRED','REJECTED')),
  received_at TIMESTAMPTZ NOT NULL,
  processed_at TIMESTAMPTZ,
  outcome_code TEXT CHECK (outcome_code IS NULL OR char_length(outcome_code) BETWEEN 1 AND 128),
  UNIQUE (provider, merchant_id, event_id),
  CHECK (
    (state = 'RECEIVED' AND processed_at IS NULL)
    OR (state <> 'RECEIVED' AND processed_at IS NOT NULL)
  )
);
CREATE INDEX ix_payment_provider_events_state_received ON payment_provider_events(state, received_at, event_row_id);
CREATE INDEX ix_payment_provider_events_payment_received ON payment_provider_events(payment_id, received_at, event_row_id);

CREATE TABLE payment_provider_event_conflicts (
  conflict_id TEXT PRIMARY KEY NOT NULL CHECK (char_length(conflict_id) BETWEEN 1 AND 255),
  provider TEXT NOT NULL CHECK (provider = 'hyperswitch'),
  merchant_id TEXT NOT NULL CHECK (char_length(merchant_id) BETWEEN 1 AND 256),
  event_id TEXT NOT NULL CHECK (char_length(event_id) BETWEEN 1 AND 255),
  existing_payload_sha256 TEXT NOT NULL CHECK (existing_payload_sha256 ~ '^[0-9a-f]{64}$'),
  incoming_payload_sha256 TEXT NOT NULL CHECK (incoming_payload_sha256 ~ '^[0-9a-f]{64}$'),
  state TEXT NOT NULL DEFAULT 'OPEN' CHECK (state IN ('OPEN','RESOLVED')),
  occurrence_count BIGINT NOT NULL DEFAULT 1 CHECK (occurrence_count >= 1),
  version BIGINT NOT NULL DEFAULT 1 CHECK (version >= 1),
  first_seen_at TIMESTAMPTZ NOT NULL,
  last_seen_at TIMESTAMPTZ NOT NULL CHECK (last_seen_at >= first_seen_at),
  resolved_at TIMESTAMPTZ,
  resolution_code TEXT CHECK (resolution_code IS NULL OR char_length(resolution_code) BETWEEN 1 AND 128),
  UNIQUE (provider, merchant_id, event_id, incoming_payload_sha256),
  CHECK (existing_payload_sha256 <> incoming_payload_sha256),
  CHECK (
    (state = 'OPEN' AND resolved_at IS NULL AND resolution_code IS NULL)
    OR (state = 'RESOLVED' AND resolved_at IS NOT NULL AND resolution_code IS NOT NULL)
  )
);
CREATE INDEX ix_payment_provider_event_conflicts_state_last_seen
  ON payment_provider_event_conflicts(state, last_seen_at, conflict_id);
CREATE INDEX ix_payment_provider_event_conflicts_identity
  ON payment_provider_event_conflicts(provider, merchant_id, event_id);

CREATE FUNCTION w07_d104_order_payment_source_guard()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  CASE TG_ARGV[0]
    WHEN 'orders_insert_idempotency' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.order_create_idempotency i
        WHERE i.customer_id = NEW.customer_id
          AND i.operation_key = 'POST /v1/commerce/orders'
          AND i.state = 'COMPLETED'
          AND i.response_json IS NOT NULL
          AND (i.response_json::jsonb ->> 'orderId') = NEW.order_id
      ) THEN
        RAISE EXCEPTION 'order requires a matching completed idempotency response'
          USING ERRCODE = '23514';
      END IF;
    WHEN 'orders_commercial_snapshot_immutable' THEN
      IF NEW.order_id IS DISTINCT FROM OLD.order_id
        OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.currency IS DISTINCT FROM OLD.currency
        OR NEW.subtotal_minor IS DISTINCT FROM OLD.subtotal_minor
        OR NEW.discount_minor IS DISTINCT FROM OLD.discount_minor
        OR NEW.tax_minor IS DISTINCT FROM OLD.tax_minor
        OR NEW.total_minor IS DISTINCT FROM OLD.total_minor
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'order commercial snapshot is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'orders_version_must_advance' THEN
      IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'order update requires version CAS and increasing updated_at' USING ERRCODE = '23514';
      END IF;
    WHEN 'orders_status_transition_guard' THEN
      IF NOT (
        (OLD.status = 'CREATED' AND NEW.status IN ('PENDING_PAYMENT','CONFIRMED','CANCELLED','FAILED'))
        OR (OLD.status = 'PENDING_PAYMENT' AND NEW.status IN ('CONFIRMED','CANCELLED','FAILED'))
        OR (OLD.status = 'CONFIRMED' AND NEW.status IN ('PROCESSING','COMPLETED','CANCELLED','FAILED'))
        OR (OLD.status = 'PROCESSING' AND NEW.status IN ('COMPLETED','FAILED'))
      ) THEN
        RAISE EXCEPTION 'invalid order state transition' USING ERRCODE = '23514';
      END IF;
    WHEN 'orders_retained' THEN
      RAISE EXCEPTION 'orders are retained for financial audit' USING ERRCODE = '23514';
    WHEN 'order_lines_require_order' THEN
      IF NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.order_id = NEW.order_id) THEN
        RAISE EXCEPTION 'order line requires an existing order' USING ERRCODE = '23514';
      END IF;
    WHEN 'order_lines_immutable_update' THEN
      RAISE EXCEPTION 'order lines are immutable' USING ERRCODE = '23514';
    WHEN 'order_lines_retained' THEN
      RAISE EXCEPTION 'order lines are retained' USING ERRCODE = '23514';
    WHEN 'order_create_idempotency_identity_immutable' THEN
      IF NEW.id IS DISTINCT FROM OLD.id
        OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.operation_key IS DISTINCT FROM OLD.operation_key
        OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
        OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
        OR NEW.created_at IS DISTINCT FROM OLD.created_at
        OR NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
        RAISE EXCEPTION 'idempotency identity is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'order_create_idempotency_terminal_immutable' THEN
      IF OLD.state IN ('COMPLETED','FAILED') THEN
        RAISE EXCEPTION 'idempotency terminal result is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payments_require_payable_order' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.orders o
        WHERE o.order_id = NEW.order_id
          AND o.customer_id = NEW.customer_id
          AND o.currency = NEW.currency
          AND o.total_minor = NEW.amount_minor
          AND o.total_minor > 0
          AND o.status IN ('CREATED','PENDING_PAYMENT')
      ) THEN
        RAISE EXCEPTION 'payment requires a matching positive payable order' USING ERRCODE = '23514';
      END IF;
    WHEN 'payments_snapshot_immutable' THEN
      IF NEW.payment_id IS DISTINCT FROM OLD.payment_id
        OR NEW.order_id IS DISTINCT FROM OLD.order_id
        OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.provider IS DISTINCT FROM OLD.provider
        OR NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
        OR NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
        OR NEW.currency IS DISTINCT FROM OLD.currency
        OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
        OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'payment commercial snapshot is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payments_version_must_advance' THEN
      IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'payment update requires version CAS and increasing updated_at' USING ERRCODE = '23514';
      END IF;
    WHEN 'payments_terminal_status_guard' THEN
      IF OLD.status IN ('succeeded','failed','cancelled','cancelled_post_capture','expired')
        AND NEW.status <> OLD.status THEN
        RAISE EXCEPTION 'terminal provider payment status cannot be reopened' USING ERRCODE = '23514';
      END IF;
    WHEN 'payments_provider_timestamp_monotonic' THEN
      IF OLD.provider_updated_at IS NOT NULL AND NEW.provider_updated_at IS NOT NULL
        AND NEW.provider_updated_at <= OLD.provider_updated_at THEN
        RAISE EXCEPTION 'provider payment update timestamp must advance' USING ERRCODE = '23514';
      END IF;
    WHEN 'payments_retained' THEN
      RAISE EXCEPTION 'payment facts are retained for financial audit' USING ERRCODE = '23514';
    WHEN 'payment_provider_events_identity_immutable' THEN
      IF NEW.event_row_id IS DISTINCT FROM OLD.event_row_id
        OR NEW.provider IS DISTINCT FROM OLD.provider
        OR NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
        OR NEW.event_id IS DISTINCT FROM OLD.event_id
        OR NEW.event_type IS DISTINCT FROM OLD.event_type
        OR NEW.payment_id IS DISTINCT FROM OLD.payment_id
        OR NEW.payload_sha256 IS DISTINCT FROM OLD.payload_sha256
        OR NEW.received_at IS DISTINCT FROM OLD.received_at THEN
        RAISE EXCEPTION 'provider webhook event identity is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_provider_events_terminal_immutable' THEN
      IF OLD.state <> 'RECEIVED' THEN
        RAISE EXCEPTION 'processed provider webhook events are immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_provider_events_retained' THEN
      RAISE EXCEPTION 'provider webhook deduplication evidence is retained' USING ERRCODE = '23514';
    WHEN 'payment_provider_event_conflicts_reference_first_receipt' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.payment_provider_events e
        WHERE e.provider = NEW.provider
          AND e.merchant_id = NEW.merchant_id
          AND e.event_id = NEW.event_id
          AND e.payload_sha256 = NEW.existing_payload_sha256
      ) THEN
        RAISE EXCEPTION 'provider event conflict must reference the immutable first receipt' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_provider_event_conflicts_identity_immutable' THEN
      IF NEW.conflict_id IS DISTINCT FROM OLD.conflict_id
        OR NEW.provider IS DISTINCT FROM OLD.provider
        OR NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
        OR NEW.event_id IS DISTINCT FROM OLD.event_id
        OR NEW.existing_payload_sha256 IS DISTINCT FROM OLD.existing_payload_sha256
        OR NEW.incoming_payload_sha256 IS DISTINCT FROM OLD.incoming_payload_sha256
        OR NEW.first_seen_at IS DISTINCT FROM OLD.first_seen_at THEN
        RAISE EXCEPTION 'provider event conflict identity is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_provider_event_conflicts_version_guard' THEN
      IF NEW.version <> OLD.version + 1
        OR NEW.last_seen_at < OLD.last_seen_at
        OR NEW.occurrence_count < OLD.occurrence_count
        OR NEW.occurrence_count > OLD.occurrence_count + 1 THEN
        RAISE EXCEPTION 'provider event conflict update requires version CAS and monotonic observation' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_provider_event_conflicts_resolved_immutable' THEN
      IF OLD.state = 'RESOLVED' THEN
        RAISE EXCEPTION 'resolved provider event conflicts are immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_provider_event_conflicts_retained' THEN
      RAISE EXCEPTION 'provider event conflict evidence is retained' USING ERRCODE = '23514';
    ELSE
      RAISE EXCEPTION 'UNKNOWN_W07_D104_TRIGGER_ACTION_%', TG_ARGV[0] USING ERRCODE = '55000';
  END CASE;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER orders_require_matching_completed_idempotency
BEFORE INSERT ON orders
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('orders_insert_idempotency');
CREATE TRIGGER orders_commercial_snapshot_immutable
BEFORE UPDATE OF order_id, customer_id, currency, subtotal_minor, discount_minor, tax_minor, total_minor, created_at ON orders
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('orders_commercial_snapshot_immutable');
CREATE TRIGGER orders_version_must_advance
BEFORE UPDATE ON orders
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('orders_version_must_advance');
CREATE TRIGGER orders_status_transition_guard
BEFORE UPDATE OF status ON orders
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('orders_status_transition_guard');
CREATE TRIGGER orders_retained
BEFORE DELETE ON orders
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('orders_retained');

CREATE TRIGGER order_lines_require_order
BEFORE INSERT ON order_lines
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('order_lines_require_order');
CREATE TRIGGER order_lines_immutable_update
BEFORE UPDATE ON order_lines
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('order_lines_immutable_update');
CREATE TRIGGER order_lines_retained
BEFORE DELETE ON order_lines
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('order_lines_retained');

CREATE TRIGGER order_create_idempotency_identity_immutable
BEFORE UPDATE OF id, customer_id, operation_key, idempotency_key, request_hash, created_at, expires_at ON order_create_idempotency
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('order_create_idempotency_identity_immutable');
CREATE TRIGGER order_create_idempotency_terminal_immutable
BEFORE UPDATE ON order_create_idempotency
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('order_create_idempotency_terminal_immutable');

CREATE TRIGGER payments_require_payable_order
BEFORE INSERT ON payments
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payments_require_payable_order');
CREATE TRIGGER payments_snapshot_immutable
BEFORE UPDATE OF payment_id, order_id, customer_id, provider, merchant_id, amount_minor, currency, idempotency_key, request_hash, created_at ON payments
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payments_snapshot_immutable');
CREATE TRIGGER payments_version_must_advance
BEFORE UPDATE ON payments
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payments_version_must_advance');
CREATE TRIGGER payments_terminal_status_guard
BEFORE UPDATE OF status ON payments
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payments_terminal_status_guard');
CREATE TRIGGER payments_provider_timestamp_monotonic
BEFORE UPDATE OF provider_updated_at ON payments
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payments_provider_timestamp_monotonic');
CREATE TRIGGER payments_retained
BEFORE DELETE ON payments
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payments_retained');

CREATE TRIGGER payment_provider_events_identity_immutable
BEFORE UPDATE OF event_row_id, provider, merchant_id, event_id, event_type, payment_id, payload_sha256, received_at ON payment_provider_events
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_events_identity_immutable');
CREATE TRIGGER payment_provider_events_terminal_immutable
BEFORE UPDATE ON payment_provider_events
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_events_terminal_immutable');
CREATE TRIGGER payment_provider_events_retained
BEFORE DELETE ON payment_provider_events
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_events_retained');

CREATE TRIGGER payment_provider_event_conflicts_reference_first_receipt
BEFORE INSERT ON payment_provider_event_conflicts
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_event_conflicts_reference_first_receipt');
CREATE TRIGGER payment_provider_event_conflicts_identity_immutable
BEFORE UPDATE OF conflict_id, provider, merchant_id, event_id, existing_payload_sha256, incoming_payload_sha256, first_seen_at ON payment_provider_event_conflicts
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_event_conflicts_identity_immutable');
CREATE TRIGGER payment_provider_event_conflicts_version_guard
BEFORE UPDATE ON payment_provider_event_conflicts
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_event_conflicts_version_guard');
CREATE TRIGGER payment_provider_event_conflicts_resolved_immutable
BEFORE UPDATE ON payment_provider_event_conflicts
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_event_conflicts_resolved_immutable');
CREATE TRIGGER payment_provider_event_conflicts_retained
BEFORE DELETE ON payment_provider_event_conflicts
FOR EACH ROW EXECUTE FUNCTION w07_d104_order_payment_source_guard('payment_provider_event_conflicts_retained');

COMMENT ON TABLE orders IS 'W07 D1-04 Order authority. Order is not a payment, ledger or entitlement fact.';
COMMENT ON TABLE payments IS 'W07 D1-04 provider-backed payment attempt. No raw webhook, card data, client secret or entitlement state is stored.';
COMMENT ON TABLE payment_provider_events IS 'Immutable signed-provider event receipt/deduplication inbox; raw webhook bodies are not persisted.';
COMMENT ON TABLE payment_provider_event_conflicts IS 'Immutable-first-receipt payload conflict facts for provider webhook reconciliation.';
